/* initialize the data array */
char segment_file[bytes];
int i;
for(i = 0; i < bytes; i++) {
	segment_file[i] = 0;
}

/* write data to img */
fseek(fp, phdr.p_offset, SEEK_SET);
fread(segment_file, phdr.p_filesz, 1, fp);
fseek(img, (*nbytes), SEEK_SET);
fwrite(segment_file, bytes, 1, img);
(*nbytes) += bytes;

return;

input.new_string:
/* the scratch buffer has to hold whatever we read from the ELF file as
 * well as everything we are about to emit, so take the larger of the two
 * (p_filesz may exceed the padded p_memsz for non-loadable segments) */
size_t bufsz = (size_t)bytes;
if (bufsz < phdr.p_filesz) {
	bufsz = phdr.p_filesz;
}

/* initialize the data array (the padding must be zeroed) */
char *segment_file = calloc(bufsz ? bufsz : 1, 1);
if (segment_file == NULL) {
	error("createimage: out of memory\n");
}

/* write data to img */
fseek(fp, phdr.p_offset, SEEK_SET);
if (phdr.p_filesz > 0) {
	fread(segment_file, phdr.p_filesz, 1, fp);
}
fseek(img, (*nbytes), SEEK_SET);
if (bytes > 0) {
