     5	
     6	futex_bucket_t futex_buckets[FUTEX_BUCKETS];
     7	
     8	void init_system_futex()
     9	{
    10	    disable_preempt();
    11	    for (int i = 0; i < FUTEX_BUCKETS; ++i) {
    12	        init_list_head(&futex_buckets[i]);
    13	    }
    14	    enable_preempt();
    15	}
    16	
    17	static int futex_hash(uint64_t x)
    18	{
    19	    // a simple hash function
    20	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
    21	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
    22	    x = x ^ (x >> 31);
    23	    return x % FUTEX_BUCKETS;
    24	}
    25	
    26	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
    27	{
    28	    int key = futex_hash((uint64_t)val_addr);
    29	    list_node_t *head = &futex_buckets[key];
    30	    for (list_node_t *p = head->next; p != head; p = p->next) {
    31	        futex_node_t *node = list_entry(p, futex_node_t, list);
    32	        if (node->futex_key == (uint64_t)val_addr) {
    33	            return node;
    34	        }
    35	    }
    36	
    37	    if (create) {
    38	        futex_node_t *node = (futex_node_t*) kmalloc(sizeof(futex_node_t));
    39	        node->futex_key = (uint64_t)val_addr;
    40	        init_list_head(&node->block_queue);
    41	        list_add_tail(&node->list, &futex_buckets[key]);
    42	        return node;
    43	    }
    44	
    45	    return NULL;
    46	}
    47	
    48	void futex_wait(volatile uint64_t *val_addr, uint64_t val)
    49	{
    50	    disable_preempt();
    51	
    52	    futex_node_t *node = get_node(val_addr,1);
    53	    assert(node != NULL);
    54	
    55	    if (*val_addr == val) {
    56	        do_block(&current_running->list, &node->block_queue);
    57	        do_scheduler();
    58	    }
    59	
    60	    enable_preempt();
    61	}
    62	
    63	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
    64	{
    65	    disable_preempt();
    66	    futex_node_t *node = get_node(val_addr, 0);
    67	
    68	    if (node != NULL) {
