void do_scheduler(void)
{
    pcb_t *prev = current_running;
    pcb_t *next;

    /* the running task voluntarily gives up the CPU, so it goes back to the
     * tail of the ready queue to keep the scheduling round-robin.
     * pid0 is the idle task, it never lives in the ready queue.
     * A task that blocked itself (or exited) is already off the ready queue
     * and must not be re-queued here. */
    if (prev != &pid0_pcb && prev->status == TASK_RUNNING) {
        prev->status = TASK_READY;
        list_add_tail(&prev->list, &ready_queue);
    }

    if (list_empty(&ready_queue)) {
        /* nothing else is runnable: fall back to the idle task */
        next = &pid0_pcb;
    } else {
        list_node_t *next_node = ready_queue.next;
        list_del(next_node);
        next = list_entry(next_node, pcb_t, list);
    }

    next->status = TASK_RUNNING;
    current_running = next;

    /* every task owns its cursor position */
    screen_cursor_x = current_running->cursor_x;
    screen_cursor_y = current_running->cursor_y;

    if (next != prev) {
        switch_to(prev, next);
    }
}

// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    pcb_t *pcb = list_entry(pcb_node, pcb_t, list);

    /* detach it from whatever queue it currently sits in ... */
    list_del(pcb_node);
    /* ... and park it at the tail of the block queue (FIFO wakeup order) */
    list_add_tail(pcb_node, queue);
    pcb->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    pcb_t *pcb = list_entry(pcb_node, pcb_t, list);

    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    pcb->status = TASK_READY;
}

