void do_mutex_lock_acquire(mutex_lock_t *lock)
{
    /* Sleep on the lock's own block queue until it is free. The loop is
     * needed because do_mutex_lock_release() only hands the lock over: an
     * unblocked task still has to re-check that nobody grabbed it first. */
    while (lock->lock.status == LOCKED) {
        do_block(&current_running->list, &(lock->block_queue));
        do_scheduler();
    }

    atomic_swap_d((uint64_t)LOCKED, (ptr_t)(&(lock->lock.status)));
}

void do_mutex_lock_release(mutex_lock_t *lock)
{
    atomic_swap_d((uint64_t)UNLOCKED, (ptr_t)(&(lock->lock.status)));

    /* hand the lock over to the task that has waited the longest */
    if (!list_empty(&(lock->block_queue))) {
