/* Host-side stand-in for arch/riscv/include/atomic.h.
 *
 * The kernel version is written in RISC-V inline assembly, which obviously
 * cannot be assembled by the host compiler.  These wrappers keep exactly the
 * same signatures and semantics on top of gcc's __atomic builtins so that the
 * real kernel sources can be compiled and executed natively by the unit
 * tests in agent_tests/.
 */
#ifndef HOST_SHIM_ATOMIC_H
#define HOST_SHIM_ATOMIC_H

#include <type.h>

static inline uint32_t atomic_swap(uint32_t val, ptr_t mem_addr)
{
    return __atomic_exchange_n((uint32_t *)mem_addr, val, __ATOMIC_SEQ_CST);
}

static inline uint64_t atomic_swap_d(uint64_t val, ptr_t mem_addr)
{
    return __atomic_exchange_n((uint64_t *)mem_addr, val, __ATOMIC_SEQ_CST);
}

static inline uint32_t atomic_add(uint32_t val, ptr_t mem_addr)
{
    return __atomic_fetch_add((uint32_t *)mem_addr, val, __ATOMIC_SEQ_CST);
}

static inline uint64_t atomic_add_d(uint64_t val, ptr_t mem_addr)
{
    return __atomic_fetch_add((uint64_t *)mem_addr, val, __ATOMIC_SEQ_CST);
}

static inline uint32_t atomic_cmpxchg(uint32_t old_val, uint32_t new_val, ptr_t mem_addr)
{
    uint32_t expected = old_val;
    __atomic_compare_exchange_n((uint32_t *)mem_addr, &expected, new_val, 0,
                                __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
    return expected;
}

static inline uint64_t atomic_cmpxchg_d(uint64_t old_val, uint64_t new_val, ptr_t mem_addr)
{
    uint64_t expected = old_val;
    __atomic_compare_exchange_n((uint64_t *)mem_addr, &expected, new_val, 0,
                                __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST);
    return expected;
}

#endif

