input.content:
/* Host-side functional test for Project 2A's cooperative scheduler and mutex.
 *
 * The real kernel sources (kernel/sched/sched.c and kernel/locking/lock.c) are
 * compiled natively and driven here.  switch_to() -- normally a chunk of
 * RISC-V assembly -- is emulated with ucontext so that tasks really do run
 * concurrently and cooperatively, which makes it possible to exercise
 * blocking/unblocking and the sleeping mutex end to end.
 */
#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <ucontext.h>

#include <os/sched.h>
#include <os/lock.h>

#undef assert
#include <stdio.h>
#include <assert.h>

/* ---- pieces of the kernel the scheduler links against ------------------ */

int screen_cursor_x;
int screen_cursor_y;

int printk(const char *fmt, ...) { (void)fmt; return 0; }
int printf(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }

#define MAX_CTX (NUM_MAX_TASK + 1)
static ucontext_t task_ctx[MAX_CTX];
static char *task_stack[MAX_CTX];

/* Emulates arch/riscv/kernel/entry.S:switch_to */
void switch_to(pcb_t *prev, pcb_t *next)
{
    if (prev == next) {
        return;
    }
    swapcontext(&task_ctx[prev->pid], &task_ctx[next->pid]);
}

static void spawn(int idx, void (*entry)(void))
{
    pcb[idx].pid = idx + 1;
    pcb[idx].type = KERNEL_THREAD;
    pcb[idx].status = TASK_READY;
    pcb[idx].preempt_count = 0;
    pcb[idx].cursor_x = 1;
    pcb[idx].cursor_y = 1;
    list_add_tail(&pcb[idx].list, &ready_queue);

    task_stack[pcb[idx].pid] = malloc(SIGSTKSZ * 4);
    getcontext(&task_ctx[pcb[idx].pid]);
    task_ctx[pcb[idx].pid].uc_stack.ss_sp = task_stack[pcb[idx].pid];
    task_ctx[pcb[idx].pid].uc_stack.ss_size = SIGSTKSZ * 4;
    task_ctx[pcb[idx].pid].uc_link = &task_ctx[0];
    makecontext(&task_ctx[pcb[idx].pid], entry, 0);
}

static void reset_world(void)
{
    memset(pcb, 0, sizeof(pcb));
    init_list_head(&ready_queue);
    pid0_pcb.pid = 0;
    pid0_pcb.status = TASK_RUNNING;
    pid0_pcb.cursor_x = 1;
    pid0_pcb.cursor_y = 1;
    current_running = &pid0_pcb;
}

/* ---- test 1: round-robin ordering -------------------------------------- */

static int rr_log[64];
static int rr_len;
static int rr_stop;

static void rr_body(void)
{
    while (!rr_stop) {
        rr_log[rr_len++] = current_running->pid;
        do_scheduler();
    }
    /* park forever; the harness stops driving us */
    while (1) {
        do_scheduler();
    }
}

static void test_round_robin(void)
{
    reset_world();
    rr_len = 0;
    rr_stop = 0;
    for (int i = 0; i < 3; i++) {
        spawn(i, rr_body);
    }

    /* Drive the idle task: every do_scheduler() from pid0 enters a task. */
    for (int i = 0; i < 9 && rr_len < 9; i++) {
        do_scheduler();
    }
    rr_stop = 1;

    assert(rr_len >= 9);
    for (int i = 0; i < 9; i++) {
        assert(rr_log[i] == (i % 3) + 1);
    }
    printf("[p2a] round-robin ordering            OK\n");
}

/* ---- test 2: block / unblock ------------------------------------------- */

static LIST_HEAD(test_block_queue);

static void test_block_unblock(void)
{
    reset_world();
    for (int i = 0; i < 3; i++) {
        spawn(i, rr_body);
    }
    init_list_head(&test_block_queue);

    /* block pcb[1] while it sits in the ready queue */
    do_block(&pcb[1].list, &test_block_queue);
    assert(pcb[1].status == TASK_BLOCKED);
    assert(test_block_queue.next == &pcb[1].list);
    assert(!list_empty(&test_block_queue));

    /* it must no longer be reachable from the ready queue */
    for (list_node_t *p = ready_queue.next; p != &ready_queue; p = p->next) {
        assert(p != &pcb[1].list);
    }

    do_unblock(&pcb[1].list);
    assert(pcb[1].status == TASK_READY);
    assert(list_empty(&test_block_queue));

