        assert(mutex_events[i + 1] == mutex_events[i] + 100);
    }
    assert(mtx.lock.status == UNLOCKED);
    assert(list_empty(&mtx.block_queue));

    printf("[p2a] sleeping mutex mutual exclusion  OK\n");
}

