static LIST_HEAD(sink_queue);

static void sink_body(void)
{
    do_block(&current_running->list, &sink_queue);
    do_scheduler();
    /* only reached after the harness wakes us again */
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_idle_fallback(void)
{
    reset_world();
    init_list_head(&sink_queue);
    for (int i = 0; i < 2; i++) {
        spawn(i, sink_body);
    }

    do_scheduler();   /* runs pcb[0], which blocks and yields   */
    do_scheduler();   /* runs pcb[1], which blocks and yields   */
    /* everything is blocked; the scheduler must come back to pid0 */
    do_scheduler();
