/* Host-side functional test for Project 2A's cooperative scheduler and mutex.
 *
 * The real kernel sources (kernel/sched/sched.c and kernel/locking/lock.c) are
 * compiled natively and driven here.  switch_to() -- normally a chunk of
 * RISC-V assembly -- is emulated with ucontext so that tasks really do run
 * concurrently and cooperatively, which makes it possible to exercise
 * blocking/unblocking and the sleeping mutex end to end.
 */
#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <ucontext.h>

#include <os/sched.h>
#include <os/lock.h>

#undef assert
#include <stdio.h>
#include <assert.h>

/* ---- pieces of the kernel the scheduler links against ------------------ */

int screen_cursor_x;
int screen_cursor_y;

int printk(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }

#define HOST_STACK_SZ (256 * 1024)
#define MAX_CTX (NUM_MAX_TASK + 1)
static ucontext_t task_ctx[MAX_CTX];
static char *task_stack[MAX_CTX];

/* Emulates arch/riscv/kernel/entry.S:switch_to */
void switch_to(pcb_t *prev, pcb_t *next)
{
    if (prev == next) {
        return;
    }
    swapcontext(&task_ctx[prev->pid], &task_ctx[next->pid]);
}

static void spawn(int idx, void (*entry)(void))
{
    pcb[idx].pid = idx + 1;
    pcb[idx].type = KERNEL_THREAD;
    pcb[idx].status = TASK_READY;
    pcb[idx].preempt_count = 0;
    pcb[idx].cursor_x = 1;
    pcb[idx].cursor_y = 1;
    list_add_tail(&pcb[idx].list, &ready_queue);

    task_stack[pcb[idx].pid] = malloc(HOST_STACK_SZ);
    getcontext(&task_ctx[pcb[idx].pid]);
    task_ctx[pcb[idx].pid].uc_stack.ss_sp = task_stack[pcb[idx].pid];
    task_ctx[pcb[idx].pid].uc_stack.ss_size = HOST_STACK_SZ;
    task_ctx[pcb[idx].pid].uc_link = &task_ctx[0];
    makecontext(&task_ctx[pcb[idx].pid], entry, 0);
}

static void reset_world(void)
{
    memset(pcb, 0, sizeof(pcb));
    init_list_head(&ready_queue);
    pid0_pcb.pid = 0;
    pid0_pcb.status = TASK_RUNNING;
    pid0_pcb.cursor_x = 1;
    pid0_pcb.cursor_y = 1;
    current_running = &pid0_pcb;
}

/* ---- test 1: round-robin ordering -------------------------------------- */

static int rr_log[64];
static int rr_len;
static int rr_stop;

static void rr_body(void)
{
    while (!rr_stop) {
        rr_log[rr_len++] = current_running->pid;
        do_scheduler();
    }
    /* park forever; the harness stops driving us */
    while (1) {
        do_scheduler();
    }
}

static void test_round_robin(void)
{
    reset_world();
    rr_len = 0;
    rr_stop = 0;
    for (int i = 0; i < 3; i++) {
        spawn(i, rr_body);
    }

    /* Drive the idle task: every do_scheduler() from pid0 enters a task. */
    for (int i = 0; i < 9 && rr_len < 9; i++) {
        do_scheduler();
    }
    rr_stop = 1;

    assert(rr_len >= 9);
    for (int i = 0; i < 9; i++) {
        assert(rr_log[i] == (i % 3) + 1);
    }
    printf("[p2a] round-robin ordering            OK\n");
}

/* ---- test 2: block / unblock ------------------------------------------- */

static LIST_HEAD(test_block_queue);

static void test_block_unblock(void)
{
    reset_world();
    for (int i = 0; i < 3; i++) {
        spawn(i, rr_body);
    }
    init_list_head(&test_block_queue);

    /* block pcb[1] while it sits in the ready queue */
    do_block(&pcb[1].list, &test_block_queue);
    assert(pcb[1].status == TASK_BLOCKED);
    assert(test_block_queue.next == &pcb[1].list);
    assert(!list_empty(&test_block_queue));

    /* it must no longer be reachable from the ready queue */
    for (list_node_t *p = ready_queue.next; p != &ready_queue; p = p->next) {
        assert(p != &pcb[1].list);
    }

    do_unblock(&pcb[1].list);
    assert(pcb[1].status == TASK_READY);
    assert(list_empty(&test_block_queue));

    int found = 0;
    for (list_node_t *p = ready_queue.next; p != &ready_queue; p = p->next) {
        if (p == &pcb[1].list) found = 1;
    }
    assert(found);
    /* unblock appends at the tail so the freshly woken task runs last */
    assert(ready_queue.prev == &pcb[1].list);

    printf("[p2a] do_block / do_unblock            OK\n");
}

/* ---- test 3: sleeping mutex -------------------------------------------- */

static mutex_lock_t mtx;
static int critical_section_owner;
static int mutex_events[64];
static int mutex_nevents;
static int mutex_done;

#define EV_ACQUIRED(pid) (100 + (pid))
#define EV_RELEASED(pid) (200 + (pid))

static void mutex_body(void)
{
    for (int round = 0; round < 2; round++) {
        do_mutex_lock_acquire(&mtx);

        /* mutual exclusion must hold across voluntary yields */
        assert(critical_section_owner == 0);
        critical_section_owner = current_running->pid;
        mutex_events[mutex_nevents++] = EV_ACQUIRED(current_running->pid);

        for (int i = 0; i < 3; i++) {
            do_scheduler();
            assert(critical_section_owner == current_running->pid);
        }

        critical_section_owner = 0;
        mutex_events[mutex_nevents++] = EV_RELEASED(current_running->pid);
        do_mutex_lock_release(&mtx);
        do_scheduler();
    }
    mutex_done++;
    /* finished: leave the ready queue for good */
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_mutex(void)
{
    reset_world();
    critical_section_owner = 0;
    mutex_nevents = 0;
    mutex_done = 0;
    do_mutex_lock_init(&mtx);
    for (int i = 0; i < 3; i++) {
        spawn(i, mutex_body);
    }

    for (int i = 0; i < 10000 && mutex_done < 3; i++) {
        do_scheduler();
    }
    assert(mutex_done == 3);

    /* events must strictly alternate acquire/release */
    assert(mutex_nevents == 12);
    for (int i = 0; i < mutex_nevents; i += 2) {
        assert(mutex_events[i] >= 100 && mutex_events[i] < 200);
        assert(mutex_events[i + 1] == mutex_events[i] + 100);
    }
    assert(mtx.lock.status == UNLOCKED);
    assert(list_empty(&mtx.block_queue));

    printf("[p2a] sleeping mutex mutual exclusion  OK\n");
}

/* ---- test 4: idle fallback when everything blocks ----------------------- */

static LIST_HEAD(sink_queue);

static void sink_body(void)
{
    do_block(&current_running->list, &sink_queue);
    do_scheduler();
    /* only reached after the harness wakes us again */
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_idle_fallback(void)
{
    reset_world();
    init_list_head(&sink_queue);
    for (int i = 0; i < 2; i++) {
        spawn(i, sink_body);
    }

    do_scheduler();   /* runs pcb[0], which blocks and yields   */
    do_scheduler();   /* runs pcb[1], which blocks and yields   */
    /* everything is blocked; the scheduler must come back to pid0 */
    do_scheduler();
    assert(current_running == &pid0_pcb);
    assert(list_empty(&ready_queue));

    do_unblock(sink_queue.next);
    do_unblock(sink_queue.next);
    assert(list_empty(&sink_queue));
    do_scheduler();
    do_scheduler();
    do_scheduler();
    assert(current_running == &pid0_pcb);

    printf("[p2a] idle fallback on empty ready q   OK\n");
}

int main(void)
{
    test_round_robin();
    test_block_unblock();
    test_mutex();
    test_idle_fallback();
    printf("[p2a] all tests passed\n");
    return 0;
}

