/*
 * The mutex is only reachable from kernel processes/threads, so giving up the
 * CPU has to go through do_scheduler() (entry.S), which simulates a trap and
 * really does store/restore the context.  Preemption is switched off around
 * the queue manipulation, but re-enabled before yielding so that the
 * disable/enable pairs always balance on the same PCB.
 */
void do_mutex_lock_acquire(mutex_lock_t *lock)
{
    disable_preempt();

    while(lock->lock.status == LOCKED){
        do_block(&current_running->list, &lock->block_queue);
        enable_preempt();
        do_scheduler();
        disable_preempt();
    }
    atomic_swap_d(LOCKED, (ptr_t)(&lock->lock.status));

    enable_preempt();
}
void do_mutex_lock_release(mutex_lock_t *lock)
{
    disable_preempt();

    atomic_swap_d(UNLOCKED, (ptr_t)(&lock->lock.status));
    /* hand the lock over to the task that has waited the longest */
    if(!list_empty(&lock->block_queue)){
        do_unblock(lock->block_queue.next);
    }

    enable_preempt();
}

