/*
 * Counting-style implementation of a binary semaphore: `sem` starts at 1, a
 * lock decrements it and a negative value tells how many tasks are queued on
 * it.  binsem_op() is only reachable through a system call, so rescheduling
 * uses scheduler() and the real switch happens in ret_from_exception().
 */
void binsem_op(int binsem_id, int op)
{
    disable_preempt();

    binsem_node_t *node = &binsem_nodes[binsem_id];

    if(op == BINSEM_OP_LOCK){
        node->sem--;
        if(node->sem < 0){
            /* the semaphore is taken, wait for the current owner */
            do_block(&current_running->list, &node->block_queue);
            scheduler();
        }
    }
    else if(op == BINSEM_OP_UNLOCK){
        node->sem++;
        if(node->sem <= 0){
            /* somebody is waiting, hand the semaphore straight over */
            do_unblock(node->block_queue.next);
            scheduler();
        }
    }

    enable_preempt();
}

