/* Host-side functional test for Project 2B's preemptive kernel.
 *
 * kernel/sched/sched.c, kernel/locking/lock.c, kernel/locking/futex.c,
 * kernel/locking/binsem.c and kernel/sched/time.c are compiled natively and
 * driven here.
 *
 * P2B splits rescheduling in two: scheduler() only re-points current_running,
 * and the actual store/restore happens later in ret_from_exception (or inside
 * the do_scheduler trampoline in entry.S).  The harness reproduces that
 * exactly: after every place where the real kernel would return through
 * ret_from_exception, ctx_return() swaps the ucontext over to whatever
 * current_running now points at.
 */
#define _GNU_SOURCE
#include <stdlib.h>
#include <string.h>
#include <ucontext.h>

#include <os/sched.h>
#include <os/lock.h>
#include <os/futex.h>
#include <os/binsem.h>
#include <os/time.h>

#undef assert
#include <stdio.h>
#include <assert.h>

/* ---- kernel bits the tested code links against ------------------------- */

int screen_cursor_x;
int screen_cursor_y;
int printk(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }

static int preempt_disabled;
void disable_preempt(void) { preempt_disabled++; }
void enable_preempt(void) { preempt_disabled--; }

/* kernel/mm/mm.c hands out fixed physical addresses, useless on the host */
void *kmalloc(size_t size) { return calloc(1, size); }
ptr_t allocPage(int numPage) { return (ptr_t)calloc(numPage, 4096); }

/* the clock the patched copy of time.c reads */
uint64_t host_tick;
uint64_t host_get_ticks(void) { return host_tick; }

#define HOST_STACK_SZ (256 * 1024)
#define MAX_CTX (NUM_MAX_TASK + 1)
static ucontext_t task_ctx[MAX_CTX];

/* emulates arch/riscv/kernel/entry.S:ret_from_exception */
static void ctx_return(pcb_t *prev)
{
    if (current_running != prev) {
        swapcontext(&task_ctx[prev->pid], &task_ctx[current_running->pid]);
    }
}

/* emulates arch/riscv/kernel/entry.S:do_scheduler */
void do_scheduler(void)
{
    pcb_t *prev = current_running;
    scheduler();
    ctx_return(prev);
}

/* emulates a timer interrupt landing on the running task */
static void timer_irq(void)
{
    pcb_t *prev = current_running;
    timer_check();
    scheduler();
    ctx_return(prev);
}

static void spawn(int idx, void (*entry)(void), uint8_t priority)
{
    pcb[idx].pid = idx + 1;
    pcb[idx].type = KERNEL_THREAD;
    pcb[idx].status = TASK_READY;
    pcb[idx].priority = priority;
    pcb[idx].ready_tick = host_tick;
    pcb[idx].cursor_x = 1;
    pcb[idx].cursor_y = 1;
    init_list_head(&pcb[idx].timer.list);
    list_add_tail(&pcb[idx].list, &ready_queue);

    getcontext(&task_ctx[pcb[idx].pid]);
    task_ctx[pcb[idx].pid].uc_stack.ss_sp = malloc(HOST_STACK_SZ);
    task_ctx[pcb[idx].pid].uc_stack.ss_size = HOST_STACK_SZ;
    task_ctx[pcb[idx].pid].uc_link = &task_ctx[0];
    makecontext(&task_ctx[pcb[idx].pid], entry, 0);
}

static void reset_world(void)
{
    memset(pcb, 0, sizeof(pcb));
    init_list_head(&ready_queue);
    init_list_head(&sleep_queue);
    init_list_head(&timer_queue);
    pid0_pcb.pid = 0;
    pid0_pcb.status = TASK_RUNNING;
    pid0_pcb.priority = 0;
    pid0_pcb.cursor_x = 1;
    pid0_pcb.cursor_y = 1;
    current_running = &pid0_pcb;
    preempt_disabled = 0;
    host_tick = 1000;
    timer_interval = 10;
    time_base = 2000;
}

/* ---- test 1: priority selection and ageing ------------------------------ */

static void never_runs(void) { while (1) do_scheduler(); }

static void test_max_priority_node(void)
{
    reset_world();
    assert(max_priority_node() == NULL);

    spawn(0, never_runs, 10);
    spawn(1, never_runs, 90);
    spawn(2, never_runs, 40);

    /* all three entered the queue at the same instant: highest wins */
    assert(max_priority_node() == &pcb[1].list);

    /* equal priorities are resolved FIFO */
    pcb[0].priority = 90;
    pcb[2].priority = 90;
    assert(max_priority_node() == &pcb[0].list);

    /* ageing: a task that has waited long enough overtakes a fresher one */
    pcb[0].priority = 10;
    pcb[1].priority = 90;
    pcb[2].priority = 40;
    pcb[0].ready_tick = host_tick - 100 * timer_interval;
    assert(max_priority_node() == &pcb[0].list);

    printf("[p2b] priority selection + ageing      OK\n");
}

/* ---- test 2: scheduler() bookkeeping ------------------------------------ */

static void test_scheduler_bookkeeping(void)
{
    reset_world();
    spawn(0, never_runs, 10);
    spawn(1, never_runs, 90);

    /* from the idle task the highest priority one is picked up */
    scheduler();
    assert(current_running == &pcb[1]);
    assert(pcb[1].status == TASK_RUNNING);
    assert(pid0_pcb.status == TASK_RUNNING);   /* idle is never queued */
    assert(screen_cursor_x == pcb[1].cursor_x);

    /* a still-running task is requeued and, being the best, picked again */
    scheduler();
    assert(current_running == &pcb[1]);

    /* once it blocks, the other one gets the CPU and the blocked task is
     * not put back into the ready queue */
    static LIST_HEAD(bq);
    init_list_head(&bq);
    do_block(&pcb[1].list, &bq);
    scheduler();
    assert(current_running == &pcb[0]);
    assert(pcb[1].status == TASK_BLOCKED);

    /* and with everything blocked the idle task comes back */
    do_block(&pcb[0].list, &bq);
    scheduler();
    assert(current_running == &pid0_pcb);
    assert(list_empty(&ready_queue));

    printf("[p2b] scheduler bookkeeping            OK\n");
}

/* ---- test 3: timer_check ------------------------------------------------ */

static int fired[8];
static void fire_cb(void *param) { fired[(long)param]++; }

static void test_timer_check(void)
{
    reset_world();
    spawn(0, never_runs, 10);
    spawn(1, never_runs, 10);

    /* timer_create() always arms the timer of current_running */
    current_running = &pcb[0];
    timer_create(fire_cb, (void *)0L, host_tick + 5);
    current_running = &pcb[1];
    timer_create(fire_cb, (void *)1L, host_tick + 50);
    current_running = &pid0_pcb;

    timer_check();
    assert(fired[0] == 0 && fired[1] == 0);

    host_tick += 10;
    timer_check();
    assert(fired[0] == 1 && fired[1] == 0);
    /* the expired timer is gone, the pending one is still queued */
    assert(timer_queue.next == &pcb[1].timer.list);
    assert(timer_queue.next->next == &timer_queue);

    /* it must not fire twice */
    timer_check();
    assert(fired[0] == 1);

    host_tick += 100;
    timer_check();
    assert(fired[1] == 1);
    assert(list_empty(&timer_queue));
    assert(preempt_disabled == 0);

    printf("[p2b] timer_check expiry               OK\n");
}

/* ---- test 4: do_sleep wakes through the timer --------------------------- */

static int sleeper_woke;

static void sleeper_body(void)
{
    pcb_t *me = current_running;
    do_sleep(1);
    ctx_return(me);           /* do_sleep() ends in ret_from_exception */
    sleeper_woke = 1;
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_do_sleep(void)
{
    reset_world();
    sleeper_woke = 0;
    spawn(0, sleeper_body, 10);

    do_scheduler();                       /* enter the sleeper, it sleeps */
    assert(pcb[0].status == TASK_BLOCKED);
    assert(current_running == &pid0_pcb);
    assert(sleeper_woke == 0);

    /* not yet due */
    timer_irq();
    assert(pcb[0].status == TASK_BLOCKED);

    host_tick += time_base * 2;
    timer_irq();                          /* fires, unblocks and switches */
    assert(sleeper_woke == 1);
    assert(list_empty(&timer_queue));

    printf("[p2b] do_sleep + timer wakeup          OK\n");
}

/* ---- test 5: kernel mutex ------------------------------------------------ */

static mutex_lock_t mtx;
static int mtx_owner;
static int mtx_rounds;

static void mutex_body(void)
{
    for (int i = 0; i < 3; i++) {
        do_mutex_lock_acquire(&mtx);
        assert(mtx_owner == 0);
        mtx_owner = current_running->pid;
        do_scheduler();
        assert(mtx_owner == current_running->pid);
        mtx_owner = 0;
        do_mutex_lock_release(&mtx);
        do_scheduler();
    }
    mtx_rounds++;
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_mutex(void)
{
    reset_world();
    mtx_owner = 0;
    mtx_rounds = 0;
    do_mutex_lock_init(&mtx);
    spawn(0, mutex_body, 10);
    spawn(1, mutex_body, 20);
    spawn(2, mutex_body, 30);

    for (int i = 0; i < 100000 && mtx_rounds < 3; i++) {
        host_tick++;
        do_scheduler();
    }
    assert(mtx_rounds == 3);
    assert(mtx.lock.status == UNLOCKED);
    assert(list_empty(&mtx.block_queue));
    assert(preempt_disabled == 0);

    printf("[p2b] kernel mutex mutual exclusion    OK\n");
}

/* ---- test 6: binary semaphore ------------------------------------------- */

static int binsem_owner;
static int binsem_rounds;
static int the_binsem;

static void sys_binsem_op(int id, int op)
{
    pcb_t *prev = current_running;
    binsem_op(id, op);
    ctx_return(prev);
}

static void binsem_body(void)
{
    for (int i = 0; i < 3; i++) {
        sys_binsem_op(the_binsem, BINSEM_OP_LOCK);
        assert(binsem_owner == 0);
        binsem_owner = current_running->pid;
        do_scheduler();
        assert(binsem_owner == current_running->pid);
        binsem_owner = 0;
        sys_binsem_op(the_binsem, BINSEM_OP_UNLOCK);
    }
    binsem_rounds++;
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_binsem(void)
{
    reset_world();
    init_system_binsem();
    binsem_owner = 0;
    binsem_rounds = 0;
    the_binsem = binsem_get(42);
    assert(the_binsem == binsem_get(42));
    assert(the_binsem >= 0 && the_binsem < BINSEM_NUMBER);
    assert(binsem_nodes[the_binsem].sem == 1);

    spawn(0, binsem_body, 10);
    spawn(1, binsem_body, 20);
    spawn(2, binsem_body, 30);

    for (int i = 0; i < 100000 && binsem_rounds < 3; i++) {
        host_tick++;
        do_scheduler();
    }
    assert(binsem_rounds == 3);
    assert(binsem_nodes[the_binsem].sem == 1);
    assert(list_empty(&binsem_nodes[the_binsem].block_queue));
    assert(preempt_disabled == 0);

    printf("[p2b] binary semaphore                 OK\n");
}

/* ---- test 7: futex ------------------------------------------------------- */

static volatile uint64_t futex_word;
static int futex_passed;

static void sys_futex_wait(volatile uint64_t *addr, uint64_t val)
{
    pcb_t *prev = current_running;
    futex_wait(addr, val);
    ctx_return(prev);
}

static void sys_futex_wakeup(volatile uint64_t *addr, int n)
{
    pcb_t *prev = current_running;
    futex_wakeup(addr, n);
    ctx_return(prev);
}

static void futex_waiter(void)
{
    sys_futex_wait(&futex_word, 1);
    /* only reachable once somebody woke us */
    assert(futex_word == 0);
    futex_passed++;
    current_running->status = TASK_EXITED;
    do_scheduler();
}

static void test_futex(void)
{
    reset_world();
    init_system_futex();
    futex_word = 1;
    futex_passed = 0;

    spawn(0, futex_waiter, 10);
    spawn(1, futex_waiter, 10);
    spawn(2, futex_waiter, 10);

    /* let all three block on the futex */
    for (int i = 0; i < 10 && !list_empty(&ready_queue); i++) {
        do_scheduler();
    }
    assert(current_running == &pid0_pcb);
    assert(pcb[0].status == TASK_BLOCKED);
    assert(pcb[1].status == TASK_BLOCKED);
    assert(pcb[2].status == TASK_BLOCKED);

    /* a value mismatch must not block */
    futex_word = 0;
    sys_futex_wait(&futex_word, 1);
    assert(current_running == &pid0_pcb);

    /* wake exactly two of the three */
    sys_futex_wakeup(&futex_word, 2);
    int woken = (pcb[0].status != TASK_BLOCKED) + (pcb[1].status != TASK_BLOCKED)
              + (pcb[2].status != TASK_BLOCKED);
    assert(woken == 2);

    for (int i = 0; i < 20 && !list_empty(&ready_queue); i++) {
        do_scheduler();
    }
    assert(futex_passed == 2);

    /* waking more than are queued is harmless */
    sys_futex_wakeup(&futex_word, 10);
    for (int i = 0; i < 20 && !list_empty(&ready_queue); i++) {
        do_scheduler();
    }
    assert(futex_passed == 3);
    sys_futex_wakeup(&futex_word, 10);

    /* an unknown key must not be created by a wakeup */
    volatile uint64_t other = 7;
    sys_futex_wakeup(&other, 1);
    assert(preempt_disabled == 0);

    printf("[p2b] futex wait / wakeup              OK\n");
}

int main(void)
{
    test_max_priority_node();
    test_scheduler_bookkeeping();
    test_timer_check();
    test_do_sleep();
    test_mutex();
    test_binsem();
    test_futex();
    printf("[p2b] all tests passed\n");
    return 0;
}

