int do_mbox_open(char *name)
{
    disable_preempt();

    /* a mailbox is shared by name: hand out the existing one if there is one */
    for(int i = 0; i < free_mailbox; i++){
        if(!kstrcmp(name, mailbox[i].name)){
            message_t *cur_message = &message[mailbox[i].id];
            (cur_message->opned)++;
            int id = mailbox[i].id;
            enable_preempt();
            return id;
        }
    }

    // create a new mailbox
    int id = -1;
    for(int i = 0; i < MBOX_NUM; i++){
        if(!message_status[i]){
            id = i;
            break;
        }
    }
    if(id == -1 || free_mailbox == MBOX_NUM){
        enable_preempt();
        return -1;
    }

    mailbox_t *new_mailbox = &mailbox[free_mailbox++];
    kstrcpy(new_mailbox->name, name);
    new_mailbox->id = id;

    // init the message
    message_t *new_message = &message[id];
    message_status[id] = 1;
    init_list_head(&new_message->wait_queue);
    new_message->opned = 1;
    new_message->msg[0] = '\0';
    new_message->msg_len = 0;

    enable_preempt();
    return new_mailbox->id;
}

