/*
 * The mailbox holds at most MAX_MBOX_LENGTH bytes.  A send that does not fit
 * blocks the sender and reports failure; user space (tiny_libc/mailbox.c)
 * retries until it succeeds, so the caller sees a blocking send.
 */
int do_mbox_send(int mailbox_id, void *msg, int msg_length)
{
    disable_preempt();

    message_t *cur_message = &message[mailbox_id];
    if(cur_message->msg_len + msg_length >= MAX_MBOX_LENGTH){
        do_block(&current_running[cpu_id]->list, &cur_message->wait_queue);
        scheduler();
        enable_preempt();
        return 0;
    }
    else{
        kmemcpy(&(cur_message->msg[cur_message->msg_len]), (char*)msg, msg_length);
        cur_message->msg_len += msg_length;
        /* the message is there now, give every waiter a chance to look */
        while(!list_empty(&cur_message->wait_queue)){
            do_unblock(cur_message->wait_queue.next);
        }
        scheduler();
        enable_preempt();
        return 1;
    }
}

/*
 * A receive that cannot be satisfied yet blocks the receiver and reports
 * failure, again leaving the retry to the user space wrapper.
 */
int do_mbox_recv(int mailbox_id, void *msg, int msg_length)
{
    disable_preempt();

    message_t *cur_message = &message[mailbox_id];
    if(msg_length > cur_message->msg_len){
        do_block(&current_running[cpu_id]->list, &cur_message->wait_queue);
        scheduler();
        enable_preempt();
        return 0;
    }
    else{
        cur_message->msg_len -= msg_length;
        kmemcpy((char*)msg, &(cur_message->msg[cur_message->msg_len]), msg_length);
        /* room has been freed, wake up any blocked sender */
        while(!list_empty(&cur_message->wait_queue)){
            do_unblock(cur_message->wait_queue.next);
        }
        scheduler();
        enable_preempt();
        return 1;
    }
}

