/* Host-side functional test for Project 3's process management and IPC.
 *
 * kernel/sched/sched.c, kernel/locking/binsem.c, kernel/syscall/mailbox.c and
 * a patched copy of kernel/sched/time.c are compiled natively and driven here.
 *
 * As in P2B, scheduler() only re-points current_running[cpu_id]; the real
 * store/restore happens in ret_from_exception.  ctx_return() reproduces that
 * with ucontext, including the very first entry into a task, which it builds
 * from the regs_context_t that do_spawn() laid down on the kernel stack.
 */
#define _GNU_SOURCE
#define timer_t host_posix_timer_t
#include <stdlib.h>
#include <string.h>
#include <ucontext.h>
#undef timer_t

#include <os/sched.h>
#include <os/binsem.h>
#include <os/mailbox.h>
#include <os/time.h>
#include <os/smp.h>

#undef assert
#define timer_t host_posix_timer_t
#include <stdio.h>
#undef timer_t
#include <assert.h>

/* ---- kernel bits the tested code links against ------------------------- */

int cpu_id;
int screen_cursor_x[NR_CPUS];
int screen_cursor_y[NR_CPUS];
int printk(const char *fmt, ...) { (void)fmt; return 0; }
void vt100_move_cursor(int x, int y) { (void)x; (void)y; }
void __global_pointer$(void) {}

static int preempt_disabled;
void disable_preempt(void) { preempt_disabled++; }
void enable_preempt(void) { preempt_disabled--; }

uint64_t host_tick;
uint64_t host_get_ticks(void) { return host_tick; }

/* kernel/mm/mm.c hands out fixed physical addresses, useless on the host, but
 * the allocator contract matters: allocPage() returns the TOP of the region
 * and freePage() recycles exactly those addresses. */
#define HOST_PAGES 256
static ptr_t page_pool[HOST_PAGES];
static int page_pool_num;
static int pages_outstanding;

ptr_t allocPage(int numPage)
{
    if (numPage == 1 && page_pool_num) {
        pages_outstanding++;
        return page_pool[--page_pool_num];
    }
    char *base = calloc(numPage, 4096);
    assert(base != NULL);
    pages_outstanding++;
    return (ptr_t)(base + (size_t)numPage * 4096);
}

void freePage(ptr_t baseAddr, int numPage)
{
    for (int i = 0; i < numPage; i++) {
        assert(page_pool_num < HOST_PAGES);
        page_pool[page_pool_num++] = baseAddr + (ptr_t)i * 4096;
    }
    pages_outstanding--;
}

void *kmalloc(size_t size) { return calloc(1, size); }

/* ---- context emulation --------------------------------------------------*/

#define HOST_STACK_SZ (256 * 1024)
#define NSLOT (NUM_MAX_TASK + NR_CPUS)
static ucontext_t ctx[NSLOT];
static pid_t ctx_pid[NSLOT];
static int ctx_live[NSLOT];

static int slot_of(pcb_t *p)
{
    for (int i = 0; i < NR_CPUS; i++) {
        if (p == &kernel_pcb[i]) return i;
    }
    return NR_CPUS + (int)(p - pcb);
}

static void task_trampoline(void);

/* emulates arch/riscv/kernel/entry.S:ret_from_exception */
static void ctx_return(pcb_t *prev)
{
    pcb_t *next = current_running[cpu_id];
    if (next == prev) return;

    int ns = slot_of(next), ps = slot_of(prev);
    if (!ctx_live[ns] || ctx_pid[ns] != next->pid) {
        /* first time this task (or this reincarnation of the slot) runs */
        ctx_live[ns] = 1;
        ctx_pid[ns] = next->pid;
        getcontext(&ctx[ns]);
        ctx[ns].uc_stack.ss_sp = malloc(HOST_STACK_SZ);
        ctx[ns].uc_stack.ss_size = HOST_STACK_SZ;
        ctx[ns].uc_link = &ctx[0];
        makecontext(&ctx[ns], task_trampoline, 0);
    }
    swapcontext(&ctx[ps], &ctx[ns]);
}

#define SYSCALL(expr)                                   \
    ({                                                  \
        pcb_t *__prev = current_running[cpu_id];        \
        long __r = (long)(expr);                        \
        ctx_return(__prev);                             \
        __r;                                            \
    })

#define SYSCALL_V(expr)                                 \
    do {                                                \
        pcb_t *__prev = current_running[cpu_id];        \
        (expr);                                         \
        ctx_return(__prev);                             \
    } while (0)

static void task_trampoline(void)
{
    pcb_t *me = current_running[cpu_id];
    regs_context_t *r = (regs_context_t *)me->kernel_sp;
    void (*entry)(long) = (void (*)(long))r->sepc;
    long arg = (long)r->regs[10];

    /* the register frame do_spawn() built must describe the task exactly */
    assert(r->regs[1] == r->sepc);            /* ra == entry point */
    assert(r->regs[2] == me->user_stack_base);/* sp == user stack   */
    assert(r->sscratch == (reg_t)me);         /* sscratch == pcb    */

    entry(arg);
    /* a user main() that returns falls into sys_exit() */
    SYSCALL_V(do_exit());
    assert(0);   /* never reached */
}

/* emulates the reaper loop at the end of init/main.c */
static void run_reaper(void)
{
    list_node_t *clean_node = kernel_pcb[0].wait_list.next;
    while (clean_node != &kernel_pcb[0].wait_list) {
        pcb_t *clean_pcb = list_entry(clean_node, pcb_t, list);
        clean_pcb->status = TASK_EXITED;
        clean_pcb->pid = -1;
        freePage(clean_pcb->kernel_stack_base, 1);
        clean_node = clean_node->next;
        list_del(clean_node->prev);
    }
}

/* emulates a timer interrupt on the current hart */
static void timer_irq(void)
{
    pcb_t *prev = current_running[cpu_id];
    timer_check();
    scheduler();
    ctx_return(prev);
}

/* run the idle task until nothing is runnable any more */
static void run_until_idle(int max_steps)
{
    for (int i = 0; i < max_steps; i++) {
        host_tick++;
        run_reaper();
        if (list_empty(&ready_queue)) break;
        timer_irq();
    }
    run_reaper();
}

static void reset_world(void)
{
    memset(pcb, 0, sizeof(pcb));
    memset(kernel_pcb, 0, sizeof(kernel_pcb));
    memset(ctx_live, 0, sizeof(ctx_live));
    init_list_head(&ready_queue);
    init_list_head(&sleep_queue);
    init_list_head(&timer_queue);
    page_pool_num = 0;
    pages_outstanding = 0;
    preempt_disabled = 0;
    host_tick = 1000;
    timer_interval = 10;
    time_base = 2000;
    process_id = 2;
    cpu_id = 0;

    for (int i = 0; i < NR_CPUS; i++) {
        kernel_pcb[i].pid = 0;
        kernel_pcb[i].type = KERNEL_PROCESS;
        kernel_pcb[i].status = TASK_RUNNING;
        kernel_pcb[i].mask = 1UL << i;
        kernel_pcb[i].cpu_id = i;
        kernel_pcb[i].cursor_x = 1;
        kernel_pcb[i].cursor_y = 1;
        kernel_pcb[i].kernel_sp = allocPage(1);
        kernel_pcb[i].kernel_stack_base = kernel_pcb[i].kernel_sp;
        init_list_head(&kernel_pcb[i].wait_list);
        init_list_head(&kernel_pcb[i].timer.list);
        current_running[i] = &kernel_pcb[i];
    }
    current_cpu_running = current_running[0];

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        pcb[i].pid = -1;
    }
    init_system_binsem();
    memset(message_status, 0, sizeof(message_status));
    memset(mailbox, 0, sizeof(mailbox));
    free_mailbox = 0;
}

/* ---- test 1: spawn / run / exit ---------------------------------------- */

static long seen_arg;
static int ran_count;

static void simple_task(long arg)
{
    seen_arg = arg;
    ran_count++;
    SYSCALL_V(do_exit());
}

static task_info_t simple_info;

static void test_spawn_and_exit(void)
{
    reset_world();
    simple_info.entry_point = (ptr_t)simple_task;
    simple_info.type = USER_PROCESS;
    simple_info.priority = 0;
    seen_arg = 0;
    ran_count = 0;

    pid_t p = do_spawn(&simple_info, (void *)0x1234L, AUTO_CLEANUP_ON_EXIT);
    assert(p == 2);
    assert(pcb[0].pid == 2);
    assert(pcb[0].status == TASK_READY);
    assert(pcb[0].mode == AUTO_CLEANUP_ON_EXIT);
    assert(pcb[0].mask == kernel_pcb[0].mask || pcb[0].mask == 3);
    assert(!list_empty(&ready_queue));

    run_until_idle(50);
    assert(ran_count == 1);
    assert(seen_arg == 0x1234L);
    /* AUTO_CLEANUP: the reaper has recycled the slot */
    assert(pcb[0].pid == -1);
    assert(pcb[0].status == TASK_EXITED);

    /* the slot is reusable and pids keep increasing */
    pid_t q = do_spawn(&simple_info, (void *)0x77L, AUTO_CLEANUP_ON_EXIT);
    assert(q == 3);
    assert(pcb[0].pid == 3);
    run_until_idle(50);
    assert(ran_count == 2 && seen_arg == 0x77L);

    printf("[p3] spawn / run / auto-cleanup exit  OK\n");
}

static void test_spawn_exhaustion(void)
{
    reset_world();
    simple_info.entry_point = (ptr_t)simple_task;
    simple_info.type = USER_PROCESS;

    for (int i = 0; i < NUM_MAX_TASK; i++) {
        assert(do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT) > 0);
    }
    assert(do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT) == -1);

    run_until_idle(500);
    assert(ran_count > 0);
    /* everything got cleaned up, so a new spawn fits again */
    assert(do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT) > 0);

    printf("[p3] spawn exhaustion returns -1      OK\n");
}

/* ---- test 2: zombie + waitpid ------------------------------------------ */

static int sys_waitpid(pid_t pid)
{
    /* handle_syscall() does sepc += 4 before dispatching; do_waitpid() may
     * rewind it to make the ecall run again once the caller is woken up. */
    regs_context_t regs;
    memset(&regs, 0, sizeof(regs));
    regs.sepc = 0x1004;

    for (;;) {
        reg_t before = regs.sepc;
        pcb_t *prev = current_running[cpu_id];
        int ret = do_waitpid(pid, 0, 0, &regs);
        ctx_return(prev);
        if (regs.sepc == before) {
            return ret;
        }
        /* the trap is taken again: a0 holds what we returned, sepc += 4 */
        pid = (pid_t)ret;
        regs.sepc += 4;
    }
}

static int child_finished;

static void zombie_child(long arg)
{
    (void)arg;
    for (int i = 0; i < 3; i++) {
        SYSCALL_V(scheduler());
    }
    child_finished = 1;
    SYSCALL_V(do_exit());
}

static int parent_saw_child_exit;

static void waiting_parent(long arg)
{
    pid_t child = (pid_t)arg;
    sys_waitpid(child);
    assert(child_finished == 1);
    parent_saw_child_exit = 1;
    SYSCALL_V(do_exit());
}

static task_info_t zombie_info, parent_info;

static void test_waitpid(void)
{
    reset_world();
    child_finished = 0;
    parent_saw_child_exit = 0;
    zombie_info.entry_point = (ptr_t)zombie_child;
    zombie_info.type = USER_PROCESS;
    parent_info.entry_point = (ptr_t)waiting_parent;
    parent_info.type = USER_PROCESS;

    pid_t child = do_spawn(&zombie_info, NULL, ENTER_ZOMBIE_ON_EXIT);
    do_spawn(&parent_info, (void *)(long)child, AUTO_CLEANUP_ON_EXIT);

    run_until_idle(2000);
    assert(child_finished == 1);
    assert(parent_saw_child_exit == 1);
    /* the parent reaped the zombie, so the slot is free again */
    assert(pcb[0].pid == -1);
    assert(list_empty(&ready_queue));

    printf("[p3] waitpid reaps a zombie child     OK\n");
}

static void test_waitpid_unknown(void)
{
    reset_world();
    assert(sys_waitpid(999) == 0);
    printf("[p3] waitpid on unknown pid returns 0 OK\n");
}

/* ---- test 3: kill -------------------------------------------------------*/

static int victim_iterations;

static void spinning_task(long arg)
{
    (void)arg;
    for (int i = 0; i < 1000; i++) {
        victim_iterations++;
        SYSCALL_V(scheduler());
    }
    SYSCALL_V(do_exit());
}

static task_info_t spin_info;

static void test_kill(void)
{
    reset_world();
    victim_iterations = 0;
    spin_info.entry_point = (ptr_t)spinning_task;
    spin_info.type = USER_PROCESS;

    pid_t victim = do_spawn(&spin_info, NULL, AUTO_CLEANUP_ON_EXIT);
    assert(do_kill(12345) == 0);           /* unknown pid */

    /* let it run a couple of rounds, then kill it from the idle task */
    for (int i = 0; i < 5; i++) {
        host_tick++;
        timer_irq();
    }
    int before = victim_iterations;
    assert(before > 0);

    assert(do_kill(victim) == 1);
    run_until_idle(200);
    assert(victim_iterations == before);   /* it really stopped */
    assert(pcb[0].pid == -1);
    assert(list_empty(&ready_queue));
    /* killing it twice is refused */
    assert(do_kill(victim) == 0);

    printf("[p3] kill stops and reclaims a task   OK\n");
}

/* ---- test 4: binary semaphore, and its release on exit ------------------ */

static int sem_owner;
static int sem_rounds;
static int the_sem;

static void binsem_task(long arg)
{
    (void)arg;
    for (int i = 0; i < 3; i++) {
        SYSCALL_V(binsem_op(the_sem, BINSEM_OP_LOCK));
        assert(sem_owner == 0);
        sem_owner = current_running[cpu_id]->pid;
        SYSCALL_V(scheduler());
        assert(sem_owner == current_running[cpu_id]->pid);
        sem_owner = 0;
        SYSCALL_V(binsem_op(the_sem, BINSEM_OP_UNLOCK));
    }
    sem_rounds++;
    SYSCALL_V(do_exit());
}

static task_info_t binsem_info;

static void test_binsem(void)
{
    reset_world();
    sem_owner = 0;
    sem_rounds = 0;
    the_sem = binsem_get(42);
    assert(the_sem == binsem_get(42));
    binsem_info.entry_point = (ptr_t)binsem_task;
    binsem_info.type = USER_PROCESS;

    for (int i = 0; i < 3; i++) {
        do_spawn(&binsem_info, NULL, AUTO_CLEANUP_ON_EXIT);
    }
    run_until_idle(20000);

    assert(sem_rounds == 3);
    assert(binsem_nodes[the_sem].sem == 1);
    assert(list_empty(&binsem_nodes[the_sem].block_queue));

    printf("[p3] binary semaphore exclusion       OK\n");
}

/* a task that grabs the semaphore and then dies without releasing it */
static void selfish_task(long arg)
{
    (void)arg;
    SYSCALL_V(binsem_op(the_sem, BINSEM_OP_LOCK));
    SYSCALL_V(do_exit());
}

static int rescued;

static void rescued_task(long arg)
{
    (void)arg;
    SYSCALL_V(binsem_op(the_sem, BINSEM_OP_LOCK));
    rescued = 1;
    SYSCALL_V(binsem_op(the_sem, BINSEM_OP_UNLOCK));
    SYSCALL_V(do_exit());
}

static task_info_t selfish_info, rescued_info;

static void test_binsem_released_on_exit(void)
{
    reset_world();
    rescued = 0;
    the_sem = binsem_get(7);
    selfish_info.entry_point = (ptr_t)selfish_task;
    selfish_info.type = USER_PROCESS;
    rescued_info.entry_point = (ptr_t)rescued_task;
    rescued_info.type = USER_PROCESS;

    do_spawn(&selfish_info, NULL, AUTO_CLEANUP_ON_EXIT);
    do_spawn(&rescued_info, NULL, AUTO_CLEANUP_ON_EXIT);
    run_until_idle(2000);

    assert(rescued == 1);
    assert(binsem_nodes[the_sem].sem == 1);

    printf("[p3] exit hands back held semaphores  OK\n");
}

/* ---- test 5: mailbox ---------------------------------------------------- */

static int mbox_value;
static int mbox_done;

static void mbox_sender(long arg)
{
    (void)arg;
    int id = SYSCALL(do_mbox_open("chan"));
    int payload = 0xbeef;
    while (!SYSCALL(do_mbox_send(id, &payload, sizeof(payload)))) {
        ;
    }
    SYSCALL_V(do_exit());
}

static void mbox_receiver(long arg)
{
    (void)arg;
    int id = SYSCALL(do_mbox_open("chan"));
    int got = 0;
    while (!SYSCALL(do_mbox_recv(id, &got, sizeof(got)))) {
        ;
    }
    mbox_value = got;
    mbox_done = 1;
    SYSCALL_V(do_exit());
}

static task_info_t send_info, recv_info;

static void test_mailbox(void)
{
    reset_world();
    mbox_value = 0;
    mbox_done = 0;

    /* names map onto one shared mailbox, distinct names onto distinct ones */
    int a = do_mbox_open("alpha");
    int b = do_mbox_open("beta");
    int a2 = do_mbox_open("alpha");
    assert(a >= 0 && b >= 0);
    assert(a == a2);
    assert(a != b);
    assert(message[a].opned == 2);
    do_mbox_close(a);
    do_mbox_close(a);
    assert(message_status[a] == 0);

    recv_info.entry_point = (ptr_t)mbox_receiver;
    recv_info.type = USER_PROCESS;
    send_info.entry_point = (ptr_t)mbox_sender;
    send_info.type = USER_PROCESS;

    /* the receiver runs first and has to block on the empty mailbox */
    do_spawn(&recv_info, NULL, AUTO_CLEANUP_ON_EXIT);
    do_spawn(&send_info, NULL, AUTO_CLEANUP_ON_EXIT);
    run_until_idle(5000);

    assert(mbox_done == 1);
    assert(mbox_value == 0xbeef);

    printf("[p3] mailbox open / send / recv       OK\n");
}

static void test_mailbox_full(void)
{
    reset_world();
    int id = do_mbox_open("full");
    char buf[MAX_MBOX_LENGTH];
    memset(buf, 'x', sizeof(buf));

    /* a message that does not fit is rejected, and the caller is parked */
    current_running[cpu_id] = &pcb[0];
    pcb[0].pid = 99;
    pcb[0].status = TASK_RUNNING;
    pcb[0].mask = 3;
    init_list_head(&pcb[0].wait_list);
    assert(do_mbox_send(id, buf, MAX_MBOX_LENGTH) == 0);
    assert(pcb[0].status == TASK_BLOCKED);
    assert(message[id].wait_queue.next == &pcb[0].list);
    current_running[cpu_id] = &kernel_pcb[0];

    /* a smaller one goes through and wakes the blocked sender */
    assert(do_mbox_send(id, buf, 8) == 1);
    assert(message[id].msg_len == 8);
    assert(pcb[0].status == TASK_READY);

    /* asking for more than is stored fails */
    char out[16];
    assert(do_mbox_recv(id, out, 16) == 0);
    assert(do_mbox_recv(id, out, 8) == 1);
    assert(message[id].msg_len == 0);
    for (int i = 0; i < 8; i++) assert(out[i] == 'x');

    printf("[p3] mailbox capacity + blocking      OK\n");
}

/* ---- test 6: cpu affinity ----------------------------------------------- */

static void test_affinity(void)
{
    reset_world();
    simple_info.entry_point = (ptr_t)simple_task;
    simple_info.type = USER_PROCESS;

    do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT);
    do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT);
    pcb[0].mask = 1;   /* core 0 only */
