    cpu_id = 1;
    assert(max_priority_node() == &pcb[1].list);

    pcb[0].mask = 2;
    cpu_id = 0;
    assert(max_priority_node() == &pcb[1].list);
    pcb[1].mask = 2;
    assert(max_priority_node() == NULL);

    /* with nothing runnable the scheduler falls back to this hart's idle */
    cpu_id = 0;
    scheduler();
    assert(current_running[0] == &kernel_pcb[0]);
    assert(current_cpu_running == &kernel_pcb[0]);

    /* do_taskset changes affinity by pid */
    assert(do_taskset(pcb[0].pid, 3) == 1);
    assert(pcb[0].mask == 3);
    assert(do_taskset(4242, 3) == 0);
    assert(max_priority_node() == &pcb[0].list);

    printf("[p3] cpu affinity masks               OK\n");
}

/* ---- test 7: priority ageing ------------------------------------------- */

static void test_priority(void)
{
    reset_world();
    simple_info.entry_point = (ptr_t)simple_task;
    simple_info.type = USER_PROCESS;

    do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT);
    do_spawn(&simple_info, NULL, AUTO_CLEANUP_ON_EXIT);
    pcb[0].priority = 10;
